func TestObsVM(t *testing.T) {
	t.Run("bin", func(t *testing.T) {
		testDataBin(t, obsVMTests)
	})
	t.Run("ascii", func(t *testing.T) {
		testDataAscii(t, obsVMTests)
	})
}

func fixupObsVMForAscii(m *ObsVM) *ObsVM {
	r := *m
	r.Obs = append([]ObsVMObs(nil), m.Obs...)
	for i := range r.Obs {
		fixupFloat(&r.Obs[i].PSR, "%.3f")
		fixupFloat(&r.Obs[i].ADR, "%.6f")
		fixupFloat32(&r.Obs[i].Dopp, "%.3f")
		fixupFloat32(&r.Obs[i].LockTime, "%.3f")
	}
	return &r
}
